    inline void from_json(const nlohmann::json& j, PhysicsAssetRootDto& v)
    {
        j.at("version").get_to(v.version);
        if (j.contains("archetypes"))
        {
            v.archetypes.clear();
            for (const auto& [key, item] : j.at("archetypes").items())
                v.archetypes[key] = ToPolymorphic<PhysicsArchetypeDto>(item);
        }
        if (j.contains("cct_bodies"))
            j.at("cct_bodies").get_to(v.cctBodies);
        if (j.contains("char_move_configs"))
            j.at("char_move_configs").get_to(v.charMoveConfigs);
        if (j.contains("dyn_bodies"))
            j.at("dyn_bodies").get_to(v.dynBodies);
        if (j.contains("kinematic_driver_configs"))
            j.at("kinematic_driver_configs").get_to(v.kinematicDriverConfigs);
        if (j.contains("materials"))
            j.at("materials").get_to(v.materials);
        if (j.contains("meshes"))
            j.at("meshes").get_to(v.meshes);
        if (j.contains("projectile_configs"))
            j.at("projectile_configs").get_to(v.projectileConfigs);
        if (j.contains("shapes"))
            j.at("shapes").get_to(v.shapes);
    }

    inline void to_json(nlohmann::json& j, const PhysicsAssetRootDto& v)
    {
        j = nlohmann::json::object();
        j["version"] = v.version;
        j["archetypes"] = nlohmann::json::object();
        for (const auto& [key, item] : v.archetypes)
            j["archetypes"][key] = item ? FromPolymorphic<PhysicsArchetypeDto>(item) : nlohmann::json(nullptr);
        j["cct_bodies"] = v.cctBodies;
        j["char_move_configs"] = v.charMoveConfigs;
        j["dyn_bodies"] = v.dynBodies;
        j["kinematic_driver_configs"] = v.kinematicDriverConfigs;
        j["materials"] = v.materials;
        j["meshes"] = v.meshes;
        j["projectile_configs"] = v.projectileConfigs;
        j["shapes"] = v.shapes;
    }

