    template<>
    inline std::unique_ptr<PhysicsArchetypeDto> ToPolymorphic<PhysicsArchetypeDto>(const nlohmann::json& j)
    {
        const std::string discriminator = j.at("body_type").get<std::string>();

        if (discriminator == "rigid_body")
            return std::make_unique<RigidPhysicsArchetypeDto>(j.get<RigidPhysicsArchetypeDto>());
        if (discriminator == "character_body")
            return std::make_unique<CharacterPhysicsArchetypeDto>(j.get<CharacterPhysicsArchetypeDto>());

        throw std::runtime_error("Unknown discriminator for PhysicsArchetypeDto: " + discriminator);
    }

    template<>
    inline nlohmann::json FromPolymorphic<PhysicsArchetypeDto>(const std::unique_ptr<PhysicsArchetypeDto>& value)
    {
        if (!value)
            return nullptr;

        if (const auto* branchValue = dynamic_cast<const RigidPhysicsArchetypeDto*>(value.get()))
            return nlohmann::json(*branchValue);
        if (const auto* branchValue = dynamic_cast<const CharacterPhysicsArchetypeDto*>(value.get()))
            return nlohmann::json(*branchValue);

        throw std::runtime_error("Unknown runtime type for PhysicsArchetypeDto.");
    }

    template<>
    inline std::unique_ptr<KinematicSourceDto> ToPolymorphic<KinematicSourceDto>(const nlohmann::json& j)
    {
        const std::string discriminator = j.at("source_type").get<std::string>();

        if (discriminator == "waypoint")
            return std::make_unique<WaypointSourceDto>(j.get<WaypointSourceDto>());
        if (discriminator == "curve")
            return std::make_unique<CurveSourceDto>(j.get<CurveSourceDto>());
        if (discriminator == "orbit")
            return std::make_unique<OrbitSourceDto>(j.get<OrbitSourceDto>());
        if (discriminator == "follow")
            return std::make_unique<FollowSourceDto>(j.get<FollowSourceDto>());
        if (discriminator == "network_pose")
            return std::make_unique<NetworkPoseSourceDto>(j.get<NetworkPoseSourceDto>());

        throw std::runtime_error("Unknown discriminator for KinematicSourceDto: " + discriminator);
    }

    template<>
    inline nlohmann::json FromPolymorphic<KinematicSourceDto>(const std::unique_ptr<KinematicSourceDto>& value)
    {
        if (!value)
            return nullptr;

        if (const auto* branchValue = dynamic_cast<const WaypointSourceDto*>(value.get()))
            return nlohmann::json(*branchValue);
        if (const auto* branchValue = dynamic_cast<const CurveSourceDto*>(value.get()))
            return nlohmann::json(*branchValue);
        if (const auto* branchValue = dynamic_cast<const OrbitSourceDto*>(value.get()))
            return nlohmann::json(*branchValue);
        if (const auto* branchValue = dynamic_cast<const FollowSourceDto*>(value.get()))
            return nlohmann::json(*branchValue);
        if (const auto* branchValue = dynamic_cast<const NetworkPoseSourceDto*>(value.get()))
            return nlohmann::json(*branchValue);

        throw std::runtime_error("Unknown runtime type for KinematicSourceDto.");
    }


    inline PhysicsAssetRootDto DeserializePhysicsAssetRootDto(const nlohmann::json& j)
    {
        return j.get<PhysicsAssetRootDto>();
    }

    inline nlohmann::json SerializePhysicsAssetRootDto(const PhysicsAssetRootDto& v)
    {
        return nlohmann::json(v);
    }

    inline PhysicsAssetRootDto LoadPhysicsAssetRootDto(const std::filesystem::path& path)
    {
        std::ifstream stream(path);
        if (!stream.is_open())
            throw std::runtime_error("Failed to open json file for read: " + path.string());

        nlohmann::json j;
        stream >> j;
        return DeserializePhysicsAssetRootDto(j);
    }

    inline void SavePhysicsAssetRootDto(const std::filesystem::path& path, const PhysicsAssetRootDto& v)
    {
        std::ofstream stream(path);
        if (!stream.is_open())
            throw std::runtime_error("Failed to open json file for write: " + path.string());

        stream << SerializePhysicsAssetRootDto(v).dump(4);
    }
